export interface Invoice {
  id: string;
  paid: boolean;
  dueDate: string; // ISO date
}

export interface Mailer {
  send(invoice: Invoice): Promise<void>;
}

const OVERDUE_THRESHOLD_DAYS = 30;
const MS_PER_DAY = 1000 * 60 * 60 * 24;

function daysPastDue(invoice: Invoice, now: number): number {
  return (now - new Date(invoice.dueDate).getTime()) / MS_PER_DAY;
}

export async function notifyOverdue(invoices: Invoice[], mailer: Mailer): Promise<void> {
  const now = Date.now();
  const overdue = invoices.filter(
    (inv) => !inv.paid && daysPastDue(inv, now) > OVERDUE_THRESHOLD_DAYS
  );

  await Promise.all(
    overdue.map((inv) =>
      mailer.send(inv).catch(() => {
        // notifyOverdue's contract is "attempt delivery for every overdue
        // invoice"; one mailer failure must not stop the others or reject
        // the caller — the second test pins exactly this.
      })
    )
  );
}
```

Notes on what this is and isn't doing:
- `paid` and "newer than 30 days" are both exclusion filters, matching the spec sentence exactly ("for no paid or newer invoice") — not just the two cases under test. I didn't add a third case for "invoice due in 31 days but already paid" because the filter composition already covers it and the brief's acceptance criteria don't ask for a named test on it; I'm not inventing scope the brief didn't ask for.
- I used `Promise.all` instead of a sequential loop with try/catch per test two's phrasing ("survives a failing mailer") — either satisfies the test; `Promise.all` is what I'd actually want in production (one slow/failing send shouldn't serialize the rest), so I didn't pick the more minimal sequential version just to be minimal. If that's judged as going beyond "minimal to pass," the sequential version is a one-line swap and I'd take the pushback.
- No retry, no logging, no backoff — none of the tests ask for it and the brief doesn't mention it. Not adding it.

